#!/usr/bin/env node
// Generates crates/tk-core/src/fold_tables.rs, so the Rust fold (policy.rs
// `fold_text`) equals the TypeScript fold in packages/tk-claude-plugin/src/core
// and packages/tk-pi character for character (integration w1 decision).
//
//   node --no-warnings crates/tk-core/gen/gen-fold-tables.mjs [--check]
//
// Sources, all from one place each:
// - Confusables: the canonical TypeScript table (Unicode confusables.txt
//   17.0.0, generated by packages/tk-claude-plugin/scripts/gen-confusables.mjs).
// - NFKD of each single code point, and the Mn and Me general categories:
//   this Node's ICU. The file records the Unicode version; generate with the
//   Node whose version the TypeScript side runs on (22.18 or later; the
//   cloud and CI's 22.23.4 and 24 report Unicode 17.0).
// Hangul syllables (U+AC00 to U+D7A3) are left to the algorithm in policy.rs.

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { CONFUSABLES } from "../../../packages/tk-claude-plugin/src/core/confusables.ts";
import { fold } from "../../../packages/tk-claude-plugin/src/core/fold.ts";

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, "..", "src", "fold_tables.rs");
// Every non-ASCII code point whose fold holds ASCII (what the reject list can
// see), with the TypeScript fold's result. Rust, tk-pi and the hook core all
// test against it.
const fixture = join(here, "..", "..", "..", "contracts", "fixtures", "policy", "fold.json");
const check = process.argv.includes("--check");

const rs = (s) =>
  [...s]
    .map((ch) => {
      const c = ch.codePointAt(0);
      if (c >= 0x20 && c < 0x7f && ch !== "\\" && ch !== '"') return ch;
      return `\\u{${c.toString(16)}}`;
    })
    .join("");

const isSurrogate = (c) => c >= 0xd800 && c <= 0xdfff;
const isHangul = (c) => c >= 0xac00 && c <= 0xd7a3;
const MARK = /^[\p{Mn}\p{Me}]$/u;

const decomp = [];
const marks = [];
let start = -1;
for (let c = 0x80; c <= 0x10ffff; c++) {
  if (isSurrogate(c)) continue;
  const ch = String.fromCodePoint(c);
  const isMark = MARK.test(ch);
  if (isMark && start < 0) start = c;
  if (!isMark && start >= 0) {
    marks.push([start, c - 1]);
    start = -1;
  }
  if (isHangul(c)) continue;
  const d = ch.normalize("NFKD");
  if (d !== ch) decomp.push([c, d]);
}
if (start >= 0) marks.push([start, 0x10ffff]);

const conf = [...CONFUSABLES.entries()].sort((a, b) => a[0] - b[0]);

const lines = [
  "// GENERATED by crates/tk-core/gen/gen-fold-tables.mjs. Do not edit by hand.",
  `// Node ${process.version}, Unicode ${process.versions.unicode}, ICU ${process.versions.icu}.`,
  "// Confusables from packages/tk-claude-plugin/src/core/confusables.ts",
  "// (Unicode confusables.txt 17.0.0, ASCII targets only).",
  "",
  `/// Unicode version of DECOMP and MARKS (Node's ICU at generation).`,
  `pub const UNICODE_VERSION: &str = "${process.versions.unicode}";`,
  "",
  "/// One non-ASCII code point to its ASCII look-alike, sorted by code point.",
  "pub static CONFUSABLES: &[(u32, &str)] = &[",
  ...conf.map(([c, t]) => `    (0x${c.toString(16)}, "${rs(t)}"),`),
  "];",
  "",
  "/// NFKD of one code point, where it differs from the code point, sorted.",
  "/// Hangul syllables are decomposed by the algorithm instead.",
  "pub static DECOMP: &[(u32, &str)] = &[",
  ...decomp.map(([c, d]) => `    (0x${c.toString(16)}, "${rs(d)}"),`),
  "];",
  "",
  "/// Code point ranges of general category Mn or Me, inclusive, sorted.",
  "pub static MARKS: &[(u32, u32)] = &[",
  ...marks.map(([a, b]) => `    (0x${a.toString(16)}, 0x${b.toString(16)}),`),
  "];",
  "",
];
const text = lines.join("\n");

const cases = [];
for (let c = 0x80; c <= 0x10ffff; c++) {
  if (isSurrogate(c)) continue;
  const f = fold(String.fromCodePoint(c));
  if (/[\x00-\x7f]/.test(f)) cases.push([c.toString(16), f]);
}
const fixtureText = `${JSON.stringify({ about: "fold(code point) by packages/tk-claude-plugin/src/core/fold.ts; generated by crates/tk-core/gen/gen-fold-tables.mjs", unicode: process.versions.unicode, cases }, null, 0).replace(/\],\[/g, "],\n[")}\n`;

if (check) {
  const recorded = /pub const UNICODE_VERSION: &str = "([^"]+)";/.exec(readFileSync(out, "utf8"))?.[1];
  if (recorded !== process.versions.unicode) {
    console.log(`not checked: fold_tables.rs is Unicode ${recorded}, this Node is ${process.versions.unicode}; check with a Node of the same version`);
    process.exit(0);
  }
  let currentFixture = "";
  try {
    currentFixture = readFileSync(fixture, "utf8");
  } catch {}
  if (currentFixture !== fixtureText) {
    console.error("contracts/fixtures/policy/fold.json is stale: run node --no-warnings crates/tk-core/gen/gen-fold-tables.mjs");
    process.exit(1);
  }
  let current = "";
  try {
    current = readFileSync(out, "utf8");
  } catch {}
  // The header line names the Node that generated it; compare the rest.
  const body = (t) => t.split("\n").slice(2).join("\n");
  if (body(current) !== body(text)) {
    console.error("fold_tables.rs is stale: run node --no-warnings crates/tk-core/gen/gen-fold-tables.mjs");
    process.exit(1);
  }
  console.log(`fold_tables.rs current (${conf.length} confusables, ${decomp.length} decompositions, ${marks.length} mark ranges)`);
} else {
  writeFileSync(out, text);
  writeFileSync(fixture, fixtureText);
  console.log(`wrote ${fixture}: ${cases.length} cases`);
  console.log(`wrote ${out}: ${conf.length} confusables, ${decomp.length} decompositions, ${marks.length} mark ranges`);
}
